INSERT INTO material_analysis_batches (
    user_id, course_id, zip_import_id, status, item_count, est_min_seconds, est_max_seconds, est_basis
) VALUES (
    #{userId}, #{courseId}, #{zipImportId}, #{status}, #{itemCount}, #{estMinSeconds}, #{estMaxSeconds},
    #{estBasis}
)

INSERT INTO material_analysis_batch_items (
    batch_id, user_id, position, filename, source_path, size_bytes, extension, zip_entry_id, upload_state,
    est_min_seconds, est_max_seconds, est_basis, message
) VALUES (
    #{batchId}, #{userId}, #{position}, #{filename}, #{sourcePath}, #{sizeBytes}, #{extension}, #{zipEntryId},
    #{uploadState}, #{estMinSeconds}, #{estMaxSeconds}, #{estBasis}, #{message}
)

mapper.select:
SELECT * FROM material_analysis_batch_items
 WHERE batch_id = #{batchId} AND user_id = #{userId}
 ORDER BY position ASC, item_id ASC

SELECT * FROM material_analysis_batch_items
 WHERE zip_entry_id = #{zipEntryId} AND user_id = #{userId}
 ORDER BY item_id DESC LIMIT 1 FOR UPDATE

