UPDATE material_analysis_batch_items i
  JOIN material_analysis_batches b ON b.batch_id = i.batch_id
   SET i.upload_state = 'ABANDONED', i.message = #{message}
 WHERE b.zip_import_id = #{zipImportId} AND b.user_id = #{userId}
   AND i.material_id IS NULL AND i.upload_state IN ('STAGED', 'UPLOADING')

