SELECT * FROM material_analysis_batches
 WHERE user_id = #{userId} AND status IN ('STAGED', 'UPLOADING', 'ANALYZING')
 AND course_id = #{courseId}
 ORDER BY batch_id DESC
 LIMIT #{limit}

SELECT * FROM material_analysis_batches
 WHERE user_id = #{userId} AND status IN ('STAGED', 'UPLOADING', 'ANALYZING')
 AND course_id = #{courseId}
 AND batch_id < #{before}
 ORDER BY batch_id DESC
 LIMIT #{limit}

SELECT COUNT(*) FROM material_analysis_batches
 WHERE user_id = #{userId} AND status IN ('STAGED', 'UPLOADING', 'ANALYZING')
 AND course_id = #{courseId}

