UPDATE material_analysis_batch_items
   SET upload_state = 'ABANDONED', message = #{message}
 WHERE upload_state IN ('STAGED', 'UPLOADING') AND material_id IS NULL
   AND zip_entry_id IS NULL
   AND created_at < #{before}

